protected $fillable = ['category_id', 'name', 'price', 'stock'];

public function category(): BelongsTo
{
    return $this->belongsTo(Category::class);
}

protected $fillable = ['status'];

public function user(): BelongsTo
{
    return $this->belongsTo(User::class);
}

public function products(): BelongsToMany
{
    return $this->belongsToMany(Product::class)->withPivot('quantity', 'price');
}

protected function total(): Attribute
{
    return Attribute::make(
        get: fn () => $this->products->sum(fn ($p) => $p->pivot->quantity * $p->pivot->price),
    );
}

public function index()
{
    $products = Product::with('category')
        ->latest()
        ->paginate(10);

    $categories = Category::withCount('products')->get();

    return view('products.index', compact('products', 'categories'));
}

use Illuminate\Support\Facades\DB;

public function store(Request $request)
{
    $items = $request->validate([
        'items' => ['required', 'array', 'min:1'],
        'items.*.id' => ['required', 'exists:products,id'],
        'items.*.qty' => ['required', 'integer', 'min:1'],
    ])['items'];

    $order = DB::transaction(function () use ($request, $items) {
        $order = $request->user()->orders()->create(['status' => 'pending']);

        foreach ($items as $item) {
            $product = Product::findOrFail($item['id']);

            $order->products()->attach($product->id, [
                'quantity' => $item['qty'],
                'price'    => $product->price,
            ]);

            $product->decrement('stock', $item['qty']);
        }

        return $order;
    });

    return redirect()->route('orders.show', $order);
}
